from pathlib import Path
import re,zipfile,shutil
p=Path('public/index.html');s=p.read_text()
css='''
/* RuvNet story: visible cause, tool, and outcome in every chapter. */
.tooltrail{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin:25px 0 18px}.tooltrail a{font:600 11px/1.3 system-ui;letter-spacing:.03em;color:#bcecf0;text-decoration:none;border:1px solid #40dfe84d;padding:9px 12px;border-radius:30px;background:#06283c}.tooltrail span{color:#edb35f}.chapter-tool{font:600 11px/1.5 system-ui;color:#57e0e8;letter-spacing:.15em;text-transform:uppercase;margin:0 0 22px}.outcome{border-left:2px solid #e9ac58;padding:10px 0 10px 16px;color:#d0e1eb;font:14px/1.7 system-ui;margin-top:20px}.outcome b{color:#f0bd78;display:block;font-size:10px;letter-spacing:.12em;text-transform:uppercase}.toolscene{position:relative;width:100%;max-width:570px;min-height:440px;display:flex;align-items:center;justify-content:center}.toolscene .schematic{position:relative;width:100%;border:1px solid #40dfe844;border-radius:16px;padding:26px;background:linear-gradient(145deg,#082b42f5,#020d1fee);box-shadow:0 20px 90px #0006;box-sizing:border-box}.schematic .micro{font:10px/1.5 system-ui;letter-spacing:.16em;color:#70b4c9;text-transform:uppercase}.toolnode{padding:17px 20px;border:1px solid #40dfe855;border-radius:10px;background:#082338;position:relative}.toolnode strong{font:600 25px/1.2 Georgia;color:#edf8fa;display:block}.toolnode small{display:block;color:#a7c5d5;font:12px/1.5 system-ui;margin-top:5px}.toolnode .state{position:absolute;right:12px;top:12px;font:8px system-ui;color:#66e1c9;text-transform:uppercase;letter-spacing:1px}.wire{height:35px;width:1px;background:#40dfe85c;margin:auto;position:relative;overflow:hidden}.wire:after{content:'';position:absolute;height:17px;width:3px;left:-1px;background:#75f6ff;box-shadow:0 0 12px #40dfe8;animation:packet 2.4s linear infinite}.wire.delayed:after{animation-delay:1s}.wire.future{background:repeating-linear-gradient(#e9ac5888 0 4px,transparent 4px 8px)}.wire.future:after{display:none}.tooltwins{display:grid;grid-template-columns:1fr 1fr;gap:12px}.tooltwins strong{font-size:20px}.toolnode.future{border-color:#e9ac5866;background:#30281955}.toolnode.future .state{color:#e9ac58}.diagram-note{font:11px/1.6 system-ui;color:#a2bfce;margin:18px 0 0}.diagram-note a{color:#5edce8}.toolscene .stamp{font:10px/1.5 system-ui;color:#e9ac58;letter-spacing:1px;margin-bottom:15px}.solver-path{display:flex;gap:7px;margin-top:18px;align-items:center;font:12px/1.5 system-ui;color:#b6d5e2}.solver-path b{padding:11px 9px;border:1px solid #6d9bb74d;border-radius:6px}.toolscene h3{font:36px/1.1 Georgia;color:#f3c17b;margin:18px 0}.toolscene p{color:#b9cedc;font:14px/1.7 system-ui}.case-pulse{display:grid;grid-template-columns:repeat(13,1fr);gap:5px;margin:20px 0}.case-pulse i{height:12px;background:#40dfe81c;border:1px solid #40dfe833;border-radius:2px}.case-pulse i:nth-child(17n){background:#40dfe8;box-shadow:0 0 14px #40dfe866;animation:casehit 3s infinite}.case-query{display:flex;justify-content:space-between;font:12px system-ui;gap:10px;color:#f0bd78}.paused .wire:after,.paused .case-pulse i{animation-play-state:paused}.toolscene .proof{border-top:1px solid #40dfe833;padding-top:15px;font:12px/1.6 system-ui;color:#99d6d4}.topmeta a{color:#a6d9e4}@keyframes packet{from{top:-17px}to{top:40px}}@keyframes casehit{50%{opacity:.35;transform:scale(.8)}}@media(max-width:760px){.toolscene{min-height:0;margin:15px 0 25px}.toolscene .schematic{padding:20px}.tooltrail{gap:6px}.tooltrail a{font-size:10px;padding:8px 10px}.toolnode{padding:15px}.toolnode strong{font-size:23px}.tooltwins{grid-template-columns:1fr}.tooltwins strong{font-size:20px}.toolnode .state{font-size:7px}.toolscene h3{font-size:32px}.chapter-tool{font-size:9px}.case-pulse{gap:3px}.solver-path{font-size:10px}.solver-path b{padding:9px 7px}.brand:after{display:none}}@media(prefers-reduced-motion:reduce){.wire:after,.case-pulse i{animation:none}}@media print{.toolscene{min-height:0}.toolscene .schematic{background:#082338;print-color-adjust:exact}.tooltrail{display:none}}
'''
s=s.replace('</style>',css+'</style>',1)
s=s.replace('THE LEARNING JOURNEY','BUILT WITH RUVNET').replace('The learning journey / v1.1.0','RuvNet in action / v1.2.0').replace('v1.1.0','v1.2.0')
s=s.replace('<title>RiverRoo — The Learning Journey</title>','<title>RiverRoo — What we can build with RuvNet</title>')
s=s.replace('The turning point ↓','The RuvNet turning point ↓')
s=s.replace('An untrained agent. A remote AI lab. One mission: learn to play poker. Follow the experiments, the discovery, and the decisions that changed his game.','Start with an agent that knows nothing. Give him a place to run, a crew to build with, and knowledge he can use. RiverRoo is the story of what we can build with the RuvNet toolkit.')
trail='<nav class="tooltrail" aria-label="Follow the RuvNet tools"><a href="#chapter-2">RuOS</a><span>→</span><a href="#chapter-2">Ruflo</a><span>→</span><a href="#chapter-5">RuvNet Brain</a><span>→</span><a href="#chapter-5">rUv’s poker work</a><span>→</span><a href="#chapter-6">RuVector</a></nav>'
s=s.replace('<div class="start">',trail+'<div class="start">',1)
sections=re.findall(r'<section\b.*?</section>',s)
def patch(n,heading,body,scene,outcome,tool,name=None):
 global s
 old=sections[n-1];new=old
 new=re.sub(r'<h[12] id="s'+str(n)+r'">.*?</h[12]>',f'<h2 id="s{n}">{heading}</h2>',new,count=1)
 new=re.sub(r'<p class="body">.*?</p>',f'<p class="body">{body}</p>',new,count=1)
 if scene:new=re.sub(r'<div class="scene\b.*?</section>',scene+'</div></section>',new,count=1)
 new=new.replace('<div class="copy">',f'<div class="copy"><div class="chapter-tool">{tool}</div>',1)
 # Keep existing stats and interactions, and put the practical outcome before them.
 new=new.replace('</p>',f'</p><div class="outcome"><b>What changed for RiverRoo</b>{outcome}</div>',1)
 if name:new=re.sub('data-name="[^"]+"',f'data-name="{name}"',new,1)
 s=s.replace(old,new)
def diagram(inner):return '<div class="toolscene"><div class="schematic">'+inner+'</div></div>'
node=lambda title,desc,state='Used':f'<div class="toolnode"><span class="state">{state}</span><strong>{title}</strong><small>{desc}</small></div>'
patch(2,'One phone.<br>A lab.<br><em>A working crew.</em>','The idea starts on an <strong>iPhone</strong>. <strong>RuOS</strong> gives RiverRoo a remote workspace where code and experiments can run. <strong>Ruflo</strong> coordinates the work around him.<br><br>That is the first transformation: an idea becomes a project with somewhere to execute, records to inspect, and a crew working on the next step.',diagram('<div class="stamp">01 / FROM INTENT TO EXECUTION</div>'+node('iPhone','The starting idea and conversation','Starting point')+'<div class="wire"></div>'+node('RuOS','Remote workspace · experiments · engine execution')+'<div class="wire delayed"></div>'+node('Ruflo','Tracked coordination · separate build and evidence work')+'<p class="diagram-note">Remote execution is real. The visual presentation is assembled and published from the Mac.</p>'),'He now has a place to practise and a coordinated project around him.','RuOS + Ruflo / create the working environment','RuOS + Ruflo')
patch(3,'Let him try.<br>Let him fail.<br><em>Keep the lesson.</em>','On <strong>RuOS</strong>, the early learner repeatedly tries a simple poker choice, receives a reward, and adjusts what it prefers. It begins with uninformed action values.<br><br>We can inspect the saved checkpoints rather than merely say “the bot learned.” The records eventually reach <strong>1,020,000 practice hands</strong>.',None,'Practice produces saved progress—but only inside a simplified fold/call exercise.','RuOS / run the experiment and inspect progress','Practice on RuOS')
patch(4,'Repetition<br>has a <em>ceiling.</em>','A million attempts sound impressive. But RiverRoo still sees only <strong>29 coarse groups</strong> and chooses between fold and call.<br><br>This is the moment to reach for more of the toolkit: give him better information and look for poker expertise that already exists.',None,'The bottleneck becomes visible: the learner needs a richer view of the game.','The turning point / reach beyond brute repetition','Find the ceiling')
solver=diagram('<div class="stamp">02 / DISCOVER EXISTING EXPERTISE</div>'+node('RuvNet Brain','Search source material before rebuilding from scratch','Used for research')+'<div class="wire"></div><div class="toolnode future"><span class="state">Discovered · not integrated</span><strong>rUv’s poker-darwin</strong><small>Trainer / solver · metaharness</small><div class="solver-path"><b>Practise strategy</b><span>→</span><b>Measure weakness</b><span>→</span><b>Refine configuration</b></div></div><p>Its CFR solver trains poker strategies. Darwin Mode searches solver configurations and scores them by exploitability.</p><p class="proof">Its Hold’em model is a two-street abstraction. We have not yet integrated or run it as RiverRoo’s policy.</p><p class="diagram-note"><a href="https://github.com/ruvnet/metaharness/tree/main/crates/poker-darwin">Inspect poker-darwin source ↗</a><br>Also found: <a href="https://github.com/ruvnet/local-logic/tree/main/poker">rUv’s local-logic poker agents ↗</a></p>')
patch(5,'Don’t reinvent<br>the whole<br><em>poker brain.</em>','We use <strong>RuvNet Brain</strong> to look outward. The source research locates <strong>rUv’s poker-darwin trainer/solver</strong> in metaharness, plus poker agents in local-logic.<br><br>This is why the ecosystem matters: an existing implementation gives us something concrete to inspect, compare, and potentially adapt. The next step is integration and a fair test—not assuming that discovery alone made RiverRoo stronger.',solver,'We found named, inspectable poker implementations. Their integration is still unfinished.','RuvNet Brain → rUv’s poker work / discover and reuse','Discover rUv’s poker work')
# Remove the obsolete generic discovery copy from scene 5.
s=s.replace('<div class="discovery">RuvNet Brain · the search for a stronger foundation</div><p class="footnote">The search for existing expertise continues. We distinguish what was discovered from what was integrated and tested.</p>','')
cases='<div class="case-pulse" aria-hidden="true">'+'<i></i>'*78+'</div>'
mem=diagram('<div class="stamp">03 / PUT KNOWLEDGE IN REACH</div><div class="case-query"><span>Starting hand</span><span>Opponent profile</span></div><div class="wire"></div>'+node('RuVector','Retrieve the relevant case from the reference memory')+cases+node('A contextual decision','Same cards + different opponent → potentially different action','Tested in restricted game')+'<p class="proof">1,352 / 1,352 lookup checks matched.<br>Direct lookup and vector retrieval made identical decisions.</p><p class="diagram-note">The reference-case experiment is separate from the poker-darwin discovery. No transfer from that solver has been demonstrated.</p>')
patch(6,'Give knowledge<br>a way to reach<br><em>the decision.</em>','A separate reference-case prototype gives RiverRoo <strong>169 starting-hand classes</strong>, <strong>14 opponent profiles</strong>, and <strong>2,366 cases</strong>. <strong>RuVector</strong> retrieves a relevant case when he needs to choose.<br><br>The practical idea: stop treating every opponent as the same problem. Bring the hand and opponent context into the decision.',mem,'He can consult richer conditional information. The restricted test measures whether that information helps.','RuVector / connect reference knowledge to action','RuVector memory')
# Preserve lesson control targets after replacing the visual scene.
s=s.replace('<div class="lesson-toggle" aria-label="Explore the lesson">','<div hidden id="lessonTitle"></div><div hidden id="lessonText"></div><div class="lesson-toggle" aria-label="Explore the lesson">')
# Hide obsolete toggle: the new explanatory diagram replaces it.
s=s.replace('.tooltrail{','.lesson-toggle{display:none}.tooltrail{',1)
patch(7,'Build it.<br>Check it.<br><em>Fix what fails.</em>','The first memory comparison gets worse. Inspecting the actual experiment reveals a mistake: the opponent profiles are assigned to the wrong seats.<br><br>We repair the mapping, add regression checks, and rerun on fresh deals. A tool’s name is not proof of improvement. The decision path has to be correct.',None,'The corrected evaluation shows a positive result in the restricted game.','Evidence / verify the connection between tools and outcome','Verify the connection')
patch(8,'That is the<br><em>RuvNet build story.</em>','<strong>RuOS</strong> provides the working lab. <strong>Ruflo</strong> coordinates the work. <strong>RuvNet Brain</strong> opens a path to existing poker expertise. <strong>RuVector</strong> brings conditional reference information into a decision.<br><br>The corrected reference experiment improves on its baseline. The separate full-street engine passes 12 RuOS tests. Integrating rUv’s poker solver, training a strong full-game policy, and proving that strength are still ahead.',None,'A working foundation, a measured bounded improvement, and an explicit next integration—not a finished champion.','The result / tools become a working learning system','What the tools made possible')
s=s.replace('<a href="/technical-checkpoint.html">Earlier technical checkpoint</a>','<a href="/final-report.html">Results &amp; tool-by-tool report ↗</a><a href="/play/">Play the full-street prototype ↗</a>')
s=s.replace('Offline deck ↓','Download story ↓')
p.write_text(s)
Path('STORY-CONTRACT.md').write_text('''Updated: 2026-10-23 EDT | Version 1.0.0
Created: 2026-10-23 EDT

# RiverRoo story contract
The purpose is to demonstrate what can be built with RuvNet tools through RiverRoo's journey. Every chapter must connect a problem, a tool/action, and a visible change. Start with the naive agent, iPhone intent, RuOS lab and Ruflo coordination; show practice and its ceiling; research existing rUv poker implementations through RuvNet Brain; show the separate RuVector reference-case experiment; verify results; finish with an honest working prototype and remaining integration. Do not turn the primary narrative into a benchmark report, mascot biography, or logo list. Do not imply poker-darwin integration or expert strength without execution evidence.
''')
with zipfile.ZipFile('public/RiverRoo-Presentation.zip','w',zipfile.ZIP_DEFLATED) as z:
 for f in Path('public').rglob('*'):
  if f.is_file() and f.suffix!='.zip' and f.name!='riverroo-character.png':z.write(f,f.relative_to('public'))
shutil.copy2('public/RiverRoo-Presentation.zip',Path.home()/'Documents/RiverRoo/RiverRoo-Presentation.zip')
print('Reframed all eight chapters around tool → contribution → outcome, v1.2.0; backup rebuilt.')
